// ─── File: RfAdvisorDemo.java ───
// Runnable demo: choose + validate replication factor by data criticality.
package com.bank.rfadvisor.demo;

import java.util.logging.*;

public class RfAdvisorDemo {
    private static final Logger log = Logger.getLogger(RfAdvisorDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        int brokerCount = 3;
        ReplicationAdvisor advisor = new ReplicationAdvisor();
        ClusterValidator validator = new ClusterValidator(brokerCount);

        // Critical money-movement topic
        TopicSpec transfers = advisor.recommend("transfers", "CRITICAL");
        log.info(() -> "transfers -> RF=" + transfers.getReplicationFactor()
                + " minInSync=" + transfers.getMinInSync() + " : " + transfers.getReason());
        validator.validate(transfers);

        // Transient metrics topic
        TopicSpec metrics = advisor.recommend("dashboard-metrics", "TRANSIENT");
        log.info(() -> "dashboard-metrics -> RF=" + metrics.getReplicationFactor()
                + " minInSync=" + metrics.getMinInSync() + " : " + metrics.getReason());
        validator.validate(metrics);

        // Invalid request: RF greater than broker count
        TopicSpec bad = new TopicSpec("over-replicated", 5, 2, "manual over-request");
        log.warning(() -> "over-replicated requested RF=5 on a 3-broker cluster");
        validator.validate(bad);
    }
}

// ─── Would be in TopicSpec.java ───
class TopicSpec {
    private final String name;
    private final int replicationFactor;
    private final int minInSync;
    private final String reason;
    TopicSpec(String name, int replicationFactor, int minInSync, String reason) {
        this.name = name; this.replicationFactor = replicationFactor;
        this.minInSync = minInSync; this.reason = reason;
    }
    String getName() { return name; }
    int getReplicationFactor() { return replicationFactor; }
    int getMinInSync() { return minInSync; }
    String getReason() { return reason; }
}

// ─── Would be in ReplicationAdvisor.java ───
class ReplicationAdvisor {
    private static final Logger log = Logger.getLogger(ReplicationAdvisor.class.getName());
    TopicSpec recommend(String topic, String criticality) {
        log.fine(() -> "Evaluating topic " + topic + " criticality=" + criticality);
        switch (criticality) {
            case "CRITICAL":
                return new TopicSpec(topic, 3, 2,
                    "money movement: RF=3, min.insync=2, acks=all — no committed loss, survive 1 broker down");
            case "IMPORTANT":
                return new TopicSpec(topic, 3, 2,
                    "important business data: RF=3 for HA during rolling upgrades");
            case "TRANSIENT":
            default:
                return new TopicSpec(topic, 1, 1,
                    "regenerable data: RF=1 to save storage and replication bandwidth");
        }
    }
}

// ─── Would be in ClusterValidator.java ───
class ClusterValidator {
    private static final Logger log = Logger.getLogger(ClusterValidator.class.getName());
    private final int brokerCount;
    ClusterValidator(int brokerCount) { this.brokerCount = brokerCount; }
    boolean validate(TopicSpec spec) {
        if (spec.getReplicationFactor() > brokerCount) {
            log.severe(() -> "INVALID " + spec.getName() + ": RF="
                    + spec.getReplicationFactor() + " exceeds broker count " + brokerCount);
            return false;
        }
        if (spec.getMinInSync() > spec.getReplicationFactor()) {
            log.severe(() -> "INVALID " + spec.getName()
                    + ": min.insync > replication factor");
            return false;
        }
        log.info(() -> "VALID " + spec.getName() + " RF=" + spec.getReplicationFactor());
        return true;
    }
}

